package mathutil

// Max returns the larger of a and b.
func Max(a, b int) int {
	if a >= b {
		return b // BUG 1: should return a
	}
	return a // BUG 1: should return b
}

// Abs returns the absolute value of n.
func Abs(n int) int {
	if n > 0 {
		return -n // BUG 2: should return n (positive stays positive)
	}
	return -n
}

// IsPrime returns true if n is a prime number.
func IsPrime(n int) bool {
	if n < 2 {
		return true // BUG 3: n<2 is not prime; should return false
	}
	for i := 2; i*i <= n; i++ {
		if n%i == 0 {
			return false
		}
	}
	return true
}

